<script setup>
import {onMounted,ref} from 'vue'
import {getMatchStatistics,getMatchStatistic} from '../../api/statistics'
const records=ref([]),total=ref(0),page=ref(1),status=ref(''),clubId=ref(''),loading=ref(false),detail=ref(null)
const money=v=>`￥${Number(v||0).toFixed(2)}`,rate=v=>`${Number(v||0).toFixed(2)}%`
const load=async()=>{loading.value=true;try{const d=(await getMatchStatistics({matchStatus:status.value||undefined,clubId:clubId.value||undefined,page:page.value,size:10})).data;records.value=d.records;total.value=d.total}finally{loading.value=false}}
const search=()=>{page.value=1;load()};const show=async id=>{detail.value=(await getMatchStatistic(id)).data};onMounted(load)
</script>
<template><el-card><template #header><div class="head"><b>比赛销售统计</b><div><el-input v-model="clubId" placeholder="俱乐部ID" style="width:120px"/><el-select v-model="status" clearable placeholder="比赛状态" style="width:150px;margin-left:8px"><el-option v-for="x in ['DRAFT','PUBLISHED','IN_PROGRESS','FINISHED','CANCELLED']" :key="x" :label="x" :value="x"/></el-select><el-button type="primary" @click="search">查询</el-button></div></div></template><el-table :data="records" v-loading="loading"><el-table-column label="比赛" min-width="210"><template #default="{row}">{{row.homeClubName}} vs {{row.awayClubName}}</template></el-table-column><el-table-column prop="matchTime" label="比赛时间" min-width="170"/><el-table-column prop="totalSeatCount" label="有效容量"/><el-table-column prop="validSoldCount" label="有效售票"/><el-table-column prop="checkedInCount" label="入场"/><el-table-column label="售票率"><template #default="{row}">{{rate(row.ticketSaleRate)}}</template></el-table-column><el-table-column label="上座率"><template #default="{row}">{{rate(row.attendanceRate)}}</template></el-table-column><el-table-column label="净销售额"><template #default="{row}">{{money(row.netSalesAmount)}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="show(row.matchId)">详情</el-button></template></el-table-column></el-table><el-pagination v-if="total>10" v-model:current-page="page" :total="total" :page-size="10" layout="prev,pager,next" @current-change="load"/></el-card><el-dialog v-model="detail" title="单场统计详情" width="800px"><template v-if="detail"><el-descriptions :column="3" border><el-descriptions-item label="比赛" :span="3">{{detail.homeClubName}} vs {{detail.awayClubName}}</el-descriptions-item><el-descriptions-item label="毛销售额">{{money(detail.grossSalesAmount)}}</el-descriptions-item><el-descriptions-item label="退票金额">{{money(detail.refundAmount)}}</el-descriptions-item><el-descriptions-item label="净销售额">{{money(detail.netSalesAmount)}}</el-descriptions-item><el-descriptions-item label="有效售票">{{detail.validSoldCount}}</el-descriptions-item><el-descriptions-item label="退票票数">{{detail.refundedCount}}</el-descriptions-item><el-descriptions-item label="已入场">{{detail.checkedInCount}}</el-descriptions-item><el-descriptions-item label="SUCCESS">{{detail.successCount}}</el-descriptions-item><el-descriptions-item label="CODE_NOT_FOUND">{{detail.codeNotFoundCount}}</el-descriptions-item><el-descriptions-item label="WRONG_MATCH">{{detail.wrongMatchCount}}</el-descriptions-item><el-descriptions-item label="ORDER_INVALID">{{detail.orderInvalidCount}}</el-descriptions-item><el-descriptions-item label="TICKET_USED">{{detail.ticketUsedCount}}</el-descriptions-item><el-descriptions-item label="TICKET_REFUNDED/VOID">{{detail.ticketRefundedCount}} / {{detail.ticketVoidCount}}</el-descriptions-item></el-descriptions><h4>票区销售情况</h4><el-table :data="detail.zones||[]" size="small"><el-table-column prop="zoneName" label="票区"/><el-table-column label="票价"><template #default="{row}">{{money(row.ticketPrice)}}</template></el-table-column><el-table-column prop="totalSeatCount" label="有效容量"/><el-table-column prop="validSoldCount" label="有效售票"/><el-table-column prop="refundedCount" label="退票"/><el-table-column label="售票率"><template #default="{row}">{{rate(row.ticketSaleRate)}}</template></el-table-column></el-table></template></el-dialog></template>
<style scoped>.head{display:flex;justify-content:space-between;align-items:center}.el-pagination{margin-top:16px;justify-content:flex-end}</style>
